\noindent \textbf{Question One (30 Marks)}

\begin{enumerate}[label=\alph*)]
 \item Find the set of values of \(x\) for which \(15 + x - 2x^2 > 0\) \hfill (3 marks)

 \item Factorize completely \(f(x) = 2x^3 + x^2 - 8x - 4\). Hence solve the equation \(f(x) = 0\) \hfill (6 marks)

 \item A team of ten is to be chosen from eight men and six women. In how many ways can this be done if at least three women are to be in the team. \hfill (3 marks)

 \item Let \(n(U) = 20\), \(n(A) = 16\), \(n(B) = 12\) and \(n(A^c \cap B^c) = 2\). Find \(n(A \cap B)\) \hfill (3 marks)

 \item 
 \begin{enumerate}[label=\roman*)]
 \item Simplify the proposition \(\sim (p \Rightarrow q) \lor p\) \hfill (3 marks)
 \item determine whether the proposition \((p \lor q) \Rightarrow \sim p\) is a tautology, a contradiction or neither. \hfill (2 marks)
 \end{enumerate}

 \item Find the middle term in the binomial expansion of \(\left(2 - \frac{x}{2}\right)^{12}\) \hfill (2 marks)

 \item Prove by Mathematical Induction that \(8^n - 1\) for any natural number \(n\) is divisible by 7. \hfill (4 marks)

 \item Express \(z = 8 + 8\sqrt{3}i\) in polar form \hfill (4 marks)
\end{enumerate}

