\noindent \underline{\textbf{QUESTION 1 - Compulsory- (30 Marks)}}

\begin{enumerate}[label=(\alph*)]
 \item The roots of the quadratic equation \(x^2 + 3x - 2 = 0\) are \(\alpha\) and \(\beta\). Without first evaluating the values of \(\alpha\) and \(\beta\) in the given equation, determine a quadratic equation with integer coefficients which has \(\left(\alpha - \frac{3}{\beta^2}\right)\) and \(\left(\beta - \frac{3}{\alpha^2}\right)\) as roots. \hfill (8 Marks)

 \item 
 \begin{enumerate}[label=(\roman*)]
 \item How many ways can you arrange the letters of the word KITCHEN if it must start with a consonant and end with a vowel? \hfill (3 Marks)
 \item A mixed hockey team containing 5 men and 6 women is to be chosen from 7 men and 9 women. In how many ways can this be done? \hfill (3 Marks)
 \end{enumerate}

 \item If \(n(U) = 23\), \(n(H^c) = 12\), \(n(K) = 15\), \(n(H^c \cap K^c) = 4\), find
 \begin{enumerate}[label=(\roman*)]
 \item \(n(H^c \cap K)\) \hfill (2 Marks)
 \item \(n(H \cap K)\) \hfill (2 Marks)
 \item \(n(H \cap K^c)\) \hfill (3 Marks)
 \end{enumerate}

 \item 
 \begin{enumerate}[label=(\roman*)]
 \item By using the truth table, show whether or not \((p \lor q) \land \sim p\) and \(q \land \sim p\) are logically equivalent. \hfill (3 Marks)
 \item By using Boolean algebra, show that \(\sim (p \Rightarrow q) \lor p = p\) \hfill (3 Marks)
 \end{enumerate}
\end{enumerate}

